SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_1152
WHERE (it1.id IN ('18')) AND (pi.info ILIKE '%oc%') AND it2.id = pi.info_type_id AND kt.id = t.kind_id AND non_leaf_1152.mi1_movie_id = t.id AND non_leaf_1152.n_id = pi.person_id AND non_leaf_1152.ci_movie_id = t.id AND (it2.id IN ('23')) AND (mi1.info ILIKE '%ci%') AND (kt.kind IN ('episode','movie','tv mini series','tv movie','video movie')) AND (rt.role IN ('actor','actress','composer','costume designer','director','miscellaneous crew','producer','production designer'));